import{_ as e,a as r,b as i,c as s}from"./chunks/sideview_2.Cqx9o4NU.js";import{_ as l,C as n,o as d,c,j as a,a as p,E as h,al as u}from"./chunks/framework.7vp1BMOE.js";const C=JSON.parse('{"title":"CORVON V5 Autopilot","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_controller/corvon_v5.md","filePath":"uk/flight_controller/corvon_v5.md"}'),m={name:"uk/flight_controller/corvon_v5.md"};function g(f,t,b,v,_,P){const o=n("Badge");return d(),c("div",null,[t[0]||(t[0]=a("h1",{id:"corvon-v5-autopilot",tabindex:"-1"},[p("CORVON V5 Autopilot "),a("a",{class:"header-anchor",href:"#corvon-v5-autopilot","aria-label":'Permalink to "CORVON V5 Autopilot"'},"​")],-1)),h(o,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=u('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://corvon.tech" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The CORVON V5 is based on the Pixhawk FMUv5 design standard and runs PX4 on NuttX.</p><p><img src="'+e+'" alt="CORVON V5 side view 1"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications {#specifications}&quot;">​</a></h2><ul><li><p><strong>Main FMU Processor:</strong> STM32F765IIK</p><ul><li>32 Bit Arm® Cortex®-M7, 216MHz, 2MB memory, 512KB RAM</li></ul></li><li><p><strong>On-board sensors:</strong></p><ul><li>Акселератор/гіроскоп: ICM-20689</li><li>Акселератор/гіроскоп: ICM-20602</li><li>Акселератор/гіроскоп: BMI088</li><li>Магнітометр: IST8310</li><li>Барометр: MS5611</li></ul></li><li><p><strong>Interfaces:</strong></p><ul><li>8 PWM outputs</li><li>3 виділених PWM/Capture входи на FMU</li><li>Виділений R/C вхід для CPPM</li><li>Виділений вхід R/C для Spektrum / DSM і S.Bus</li><li>Аналоговий / PWM вхід RSSI</li><li>4 загальних послідовних порти</li><li>3 I2C порти</li><li>4 шини SPI</li><li>2 CAN шини</li><li>Аналогові входи для напруги / струму з батареї</li><li>2 додаткових аналогових входи</li><li>Підтримка nARMED</li></ul></li><li><p><strong>Power System:</strong></p><ul><li>Power Brick Input: 4.75~5.5V</li><li>USB-C Power Input: 4.75~5.25V</li></ul></li><li><p><strong>Weight and Dimensions:</strong></p><ul><li>Weight: 42.1g</li><li>Dimensions: 61.2 x 40 x 15.9mm</li></ul></li><li><p><strong>Other Characteristics:</strong></p><ul><li>Operating temperature: -20 ~ 85°C (Measured value)</li></ul></li></ul><h2 id="store" tabindex="-1">Where to Buy <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Where to Buy {#store}&quot;">​</a></h2><ul><li><a href="https://corvon.tech" target="_blank" rel="noreferrer">CORVON Store</a></li></ul><h2 id="connectors-and-interfaces" tabindex="-1">Connectors and Interfaces <a class="header-anchor" href="#connectors-and-interfaces" aria-label="Permalink to &quot;Connectors and Interfaces&quot;">​</a></h2><p><img src="'+r+'" alt="Connectors and Interfaces"></p><h2 id="схема-розташування-виводів" tabindex="-1">Схема розташування виводів <a class="header-anchor" href="#схема-розташування-виводів" aria-label="Permalink to &quot;Схема розташування виводів&quot;">​</a></h2><p>Download Corvon V5 pinouts from here: <a href="https://github.com/PX4/PX4-Autopilot/raw/main/docs/assets/flight_controller/corvon_v5/corvon_v5_pinout.xlsx" target="_blank" rel="noreferrer">corvon_v5_pinout.xlsx</a></p><h2 id="налаштування-послідовного-порту" tabindex="-1">Налаштування послідовного порту <a class="header-anchor" href="#налаштування-послідовного-порту" aria-label="Permalink to &quot;Налаштування послідовного порту&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Пристрій</th><th>Порт</th><th style="text-align:center;">Flow Control</th></tr></thead><tbody><tr><td>USART1</td><td><code>/dev/ttyS0</code></td><td>GPS</td><td style="text-align:center;">-</td></tr><tr><td>USART2</td><td><code>/dev/ttyS1</code></td><td>TELEM1</td><td style="text-align:center;">Так</td></tr><tr><td>USART3</td><td><code>/dev/ttyS2</code></td><td>TELEM2</td><td style="text-align:center;">Так</td></tr><tr><td>UART4</td><td><code>/dev/ttyS3</code></td><td>TELEM4</td><td style="text-align:center;">-</td></tr><tr><td>USART6</td><td><code>/dev/ttyS4</code></td><td>RC</td><td style="text-align:center;">-</td></tr><tr><td>UART7</td><td><code>/dev/ttyS5</code></td><td>Debug Console</td><td style="text-align:center;">-</td></tr><tr><td>UART8</td><td><code>/dev/ttyS6</code></td><td>Reserved for optional onboard RTK module</td><td style="text-align:center;">-</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UART8 is reserved for an optional onboard UM982 module footprint and is not intended for general external use.</p></div><h2 id="radio_control" tabindex="-1">Radio Control <a class="header-anchor" href="#radio_control" aria-label="Permalink to &quot;Radio Control {#radio_control}&quot;">​</a></h2><p>Для того щоб керувати транспортним засобом <em>вручну</em>, потрібна система радіоуправління (RC) (PX4 не потребує системи радіоуправління для автономних режимів польоту). Вам потрібно <a href="./../getting_started/rc_transmitter_receiver">вибрати сумісний передавач/приймач</a> і <em>зв&#39;язати</em> їх таким чином, щоб вони взаємодіяли (ознайомтеся з інструкціями, що додаються до вашого конкретного передавача/приймача).</p><p>The ports and supported protocols are:</p><ul><li><code>DSM/SBUS/RSSI</code> (FMU): SBUS, DSM/DSMX, ST24, SUMD, CRSF, and GHST receivers</li><li><code>RC</code>: PPM</li></ul><p>For PPM and S.Bus receivers, a single signal wire carries all channels. If your receiver outputs individual PWM signals (one wire per channel) it must be connected via a <a href="./../getting_started/rc_transmitter_receiver">PPM encoder</a>.</p><h3 id="gps_compass" tabindex="-1">GPS &amp; Compass <a class="header-anchor" href="#gps_compass" aria-label="Permalink to &quot;GPS &amp; Compass {#gps_compass}&quot;">​</a></h3><p>PX4 supports GPS modules connected to the GPS port(s) listed below. The module should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible, with the direction marker pointing towards the front of the vehicle.</p><p>The GPS ports are:</p><ul><li><code>GPS&amp;SAFETY</code> (FMU): 10-pin JST GH (<a href="https://github.com/pixhawk/Pixhawk-Standards/blob/master/DS-009%20Pixhawk%20Connector%20Standard.pdf" target="_blank" rel="noreferrer">Pixhawk Connector Standard</a>) — GPS, compass (I2C), safety switch, buzzer, LED.</li></ul><p>Вбудований безпечний вимикач в GPS-модулі увімкнений <em>за замовчуванням</em> (коли включений, PX4 не дозволить вам готувати до польоту). To disable the safety switch press and hold it for 1 second. You can press the safety switch again to enable safety and disarm the vehicle.</p><h2 id="pwm_outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm_outputs" aria-label="Permalink to &quot;PWM Outputs {#pwm_outputs}&quot;">​</a></h2><p>This flight controller supports up to 8 FMU PWM outputs (<code>MAIN</code>).</p><p><a href="./../peripherals/dshot">DShot</a> is not supported.</p><p>The 8 outputs are in 3 groups:</p><ul><li>Outputs 1-4 in group1 (Timer1)</li><li>Outputs 5-6 in group2 (Timer4)</li><li>Outputs 7-8 in group3 (Timer12)</li></ul><p>All outputs within the same group must use the same output protocol and rate.</p><h2 id="debug_port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug_port" aria-label="Permalink to &quot;Debug Port {#debug_port}&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> and <a href="./../debug/swd_debug">SWD interface</a> operate on the <strong>FMU Debug</strong> port (<code>DSU7</code>).</p><p>The debug port (<code>DSU7</code>) has the following pinout:</p><table tabindex="0"><thead><tr><th>Pin</th><th>Сигнал</th><th>Вольтаж</th></tr></thead><tbody><tr><td>1</td><td>GND</td><td>GND</td></tr><tr><td>2</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>3</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>4</td><td>DEBUG RX</td><td>+3.3V</td></tr><tr><td>5</td><td>DEBUG TX</td><td>+3.3V</td></tr><tr><td>6</td><td>5V+</td><td>+5V</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The 5V+ pin (6) provides 5V, but the CPU logic runs at 3.3V!</p><p>Some JTAG/SWD adapters (like SEGGER J-Link) may use the Vref voltage pin to set the logic level on the SWD data lines. Connecting 5V to the adapter&#39;s <code>Vtref</code> can damage the CPU. For a direct connection to a <em>Segger Jlink</em>, we recommend you use a 3.3V source to provide <code>Vtref</code> to the JTAG adapter (i.e. providing 3.3V and <em>NOT</em> 5V).</p></div><h2 id="номінальна-напруга" tabindex="-1">Номінальна напруга <a class="header-anchor" href="#номінальна-напруга" aria-label="Permalink to &quot;Номінальна напруга&quot;">​</a></h2><p>CORVON V5 must be powered from the <strong>POWER</strong> connector during flight, and may also be powered from <strong>USB</strong> for bench testing.</p><ul><li><strong>POWER input:</strong> 4.75~5.5V</li><li><strong>USB input:</strong> 4.75~5.25V</li></ul><p>The <strong>PM2</strong> connector <strong>cannot power</strong> the flight controller. On PX4, <strong>do not use</strong> this interface.</p><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>Щоб зібрати PX4 для цього контролера:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_v5_default</span></span></code></pre></div><h2 id="встановлення-прошивки-px4" tabindex="-1">Встановлення прошивки PX4 <a class="header-anchor" href="#встановлення-прошивки-px4" aria-label="Permalink to &quot;Встановлення прошивки PX4&quot;">​</a></h2><p>Прошивку можна встановити будь-якими звичайними способами:</p><ul><li><p><strong>Build and upload the source</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> corvon_v5_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span></span></code></pre></div></li><li><p><strong>Load the firmware using <em>QGroundControl</em>.</strong> You can use either pre-built firmware or your own custom firmware.</p></li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If this target is not listed in <em>QGroundControl</em>, build and upload from source or load a custom firmware file (see <a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Installing PX4 Main, Beta or Custom Firmware</a>).</p></div><h2 id="підтримувані-платформи-конструкціі" tabindex="-1">Підтримувані платформи / Конструкції <a class="header-anchor" href="#підтримувані-платформи-конструкціі" aria-label="Permalink to &quot;Підтримувані платформи / Конструкції&quot;">​</a></h2><p>Будь-який мультикоптер / літак / наземна платформа / човен, який може керуватися звичайними RC сервоприводами або сервоприводами Futaba S-Bus. The complete set of supported configurations can be seen in the <a href="./../airframes/airframe_reference">Airframes Reference</a>.</p><h2 id="зображення" tabindex="-1">Зображення <a class="header-anchor" href="#зображення" aria-label="Permalink to &quot;Зображення&quot;">​</a></h2><p><img src="'+i+'" alt="CORVON V5 front view"><img src="'+e+'" alt="CORVON V5 side view 1"><img src="'+s+'" alt="CORVON V5 side view 2"></p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://corvon.tech" target="_blank" rel="noreferrer">Corvon Tech</a></li></ul>',53))])}const x=l(m,[["render",g]]);export{C as __pageData,x as default};
